            list.remove(cacheMap.get(key));
        }

        Node node = new Node(key, value);
        cacheMap.put(key, node);
        list.addFirst(node);

        if (cacheMap.size() > capacity) {
            Node nodeToDelete = list.getLast();
            list.remove(nodeToDelete);
            cacheMap.remove(nodeToDelete.key);
        }
    }
}

